import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Sound effects, one file each in `assets/audio/sfx/`, generated by
/// `tools/gen_audio.py`.
enum Sfx {
  shot('shot'),
  shotFire('shot_fire'),
  shotAqua('shot_aqua'),
  shotElec('shot_elec'),
  shotWood('shot_wood'),
  melee('melee'),
  toss('toss'),
  support('support'),
  heal('heal'),
  chain2('chain2'),
  chain3('chain3'),
  explosion('explosion'),
  slash('slash'),
  hitEnemy('hit_enemy'),
  hitPlayer('hit_player'),
  block('block'),
  stun('stun'),
  enemyDeath('enemy_death'),
  enemyShot('enemy_shot'),
  telegraph('telegraph'),
  newHand('new_hand'),
  win('win'),
  lose('lose'),
  tap('tap'),
  confirm('confirm'),
  cancel('cancel'),
  buy('buy'),
  reward('reward'),
  deck('deck'),
  pause('pause'),
  node('node'),
  upgrade('upgrade');

  const Sfx(this.file);

  final String file;

  /// Relative to `assets/`, as [AssetSource] wants it.
  String get path => 'audio/sfx/$file.wav';
}

/// Looping tracks in `assets/audio/music/` (placeholders from the same
/// script).
enum Music {
  map,
  battle,
  boss,
  shop;

  String get path => 'audio/music/$name.wav';
}

abstract final class AudioFiles {
  static final all = [
    for (final sfx in Sfx.values) sfx.path,
    for (final track in Music.values) track.path,
  ];
}

/// Plays every sound in the game. Does nothing until [init] (tests never
/// call it, so no plugin is touched there).
///
/// - Each effect has its own player, loaded once in [init]: replaying it
///   restarts it, and it isn't restarted within [_retrigger]. At most
///   [_voices] effects start within [_voiceWindow]; the rest are dropped.
/// - Nothing asks for audio focus (on Android each request stopped the
///   other players).
/// - Music crossfades between two looping players.
/// - Volumes and mute are saved with shared_preferences.
/// - On the web nothing can play before the first tap; music that failed
///   to start is retried on the next effect.
class GameAudio {
  GameAudio._();

  static final instance = GameAudio._();

  static const _voices = 8;
  static const _voiceWindow = Duration(milliseconds: 150);
  static const _retrigger = Duration(milliseconds: 50);
  static const _fade = Duration(milliseconds: 800);
  static const _fadeSteps = 16;

  /// A UI sound right after a tap replaces the tap's blip.
  static const _tapWindow = Duration(milliseconds: 100);

  bool _ready = false;
  SharedPreferences? _prefs;

  double musicVolume = 0.5;
  double sfxVolume = 0.8;
  bool muted = false;

  final Map<Sfx, AudioPlayer> _sfx = {};
  final Map<Sfx, DateTime> _lastPlayed = {};

  /// When the latest effects started, oldest first, for the voice cap.
  final List<DateTime> _started = [];

  final List<AudioPlayer> _music = [];
  int _active = 0;
  Music? _track;
  bool _musicPending = false;
  Timer? _fadeTimer;

  Future<void> init() async {
    try {
      final prefs = _prefs = await SharedPreferences.getInstance();
      musicVolume = prefs.getDouble('musicVolume') ?? musicVolume;
      sfxVolume = prefs.getDouble('sfxVolume') ?? sfxVolume;
      muted = prefs.getBool('muted') ?? muted;
      await AudioPlayer.global.setAudioContext(
        AudioContextConfig(
          focus: AudioContextConfigFocus.mixWithOthers,
        ).build(),
      );
      for (final sfx in Sfx.values) {
        final player = _player();
        await player.setReleaseMode(ReleaseMode.stop);
        // SoundPool: much less delay than MediaPlayer for short effects.
        if (!kIsWeb && defaultTargetPlatform == TargetPlatform.android) {
          await player.setPlayerMode(PlayerMode.lowLatency);
        }
        await player.setVolume(sfxVolume);
        await player.setSource(AssetSource(sfx.path));
        _sfx[sfx] = player;
      }
      for (var i = 0; i < 2; i++) {
        final player = _player();
        await player.setReleaseMode(ReleaseMode.loop);
        _music.add(player);
      }
      _ready = true;
    } catch (e) {
      debugPrint('Audio disabled: $e');
    }
  }

  /// The default position updater asks the platform for the position on
  /// every frame while playing, and low-latency players never stop
  /// "playing": with many effects that floods the main thread.
  static AudioPlayer _player() => AudioPlayer()..positionUpdater = null;

  void play(Sfx sfx) {
    if (!_ready) return;
    if (_musicPending) _startMusic();
    if (muted || sfxVolume == 0) return;
    final now = DateTime.now();
    final last = _lastPlayed[sfx];
    if (last != null && now.difference(last) < _retrigger) return;
    _started.removeWhere((t) => now.difference(t) >= _voiceWindow);
    if (_started.length >= _voices) return;
    _started.add(now);
    _lastPlayed[sfx] = now;

    final lastTap = _lastPlayed[Sfx.tap];
    if (sfx != Sfx.tap &&
        lastTap != null &&
        now.difference(lastTap) < _tapWindow) {
      _safe(_sfx[Sfx.tap]!.stop());
    }
    _safe(_restart(_sfx[sfx]!));
  }

  /// Stop first: on Android a low-latency player never learns that its
  /// sound ended and ignores a plain resume.
  Future<void> _restart(AudioPlayer player) async {
    await player.stop();
    await player.resume();
  }

  /// Switches to [track], crossfading; null fades out.
  void music(Music? track) {
    if (track == _track) return;
    _track = track;
    if (_ready) _startMusic();
  }

  Future<void> _startMusic() async {
    _musicPending = false;
    final track = _track;
    final from = _music[_active];
    _active = 1 - _active;
    final to = _music[_active];
    _fadeTimer?.cancel();
    if (track != null) {
      try {
        await to.setVolume(0);
        await to.play(AssetSource(track.path), volume: 0);
      } catch (_) {
        // Blocked until the first tap on the web.
        _musicPending = true;
        _active = 1 - _active;
        return;
      }
    }
    final fromVolume = from.volume;
    var step = 0;
    _fadeTimer = Timer.periodic(_fade ~/ _fadeSteps, (timer) {
      final t = ++step / _fadeSteps;
      _safe(from.setVolume(fromVolume * (1 - t)));
      if (track != null) _safe(to.setVolume(_musicLevel * t));
      if (step >= _fadeSteps) {
        timer.cancel();
        _safe(from.stop());
      }
    });
  }

  double get _musicLevel => muted ? 0 : musicVolume;

  void setMusicVolume(double volume) {
    musicVolume = volume.clamp(0, 1);
    _applyMusicVolume();
    _save();
  }

  void setSfxVolume(double volume) {
    sfxVolume = volume.clamp(0, 1);
    for (final player in _sfx.values) {
      _safe(player.setVolume(sfxVolume));
    }
    _save();
  }

  void toggleMute() {
    muted = !muted;
    _applyMusicVolume();
    _save();
  }

  void _applyMusicVolume() {
    if (!_ready || _track == null) return;
    _fadeTimer?.cancel();
    _safe(_music[_active].setVolume(_musicLevel));
    _safe(_music[1 - _active].stop());
  }

  void _save() {
    final prefs = _prefs;
    if (prefs == null) return;
    _safe(prefs.setDouble('musicVolume', musicVolume));
    _safe(prefs.setDouble('sfxVolume', sfxVolume));
    _safe(prefs.setBool('muted', muted));
  }

  /// Audio failures (a codec, a blocked autoplay) never reach the game.
  void _safe(Future<Object?> future) => unawaited(
    future.then<void>((_) {}, onError: (Object e) => debugPrint('Audio: $e')),
  );
}
